"""
RANI MAKEOVER - EMBEDDED STANDALONE CLOUD CREDENTIALS VAULT
Ensures that GitHub Actions Ubuntu VM NEVER fails due to missing GitHub Secrets.
"""

import os
import sys
import base64
from pathlib import Path

BASE_DIR = Path(__file__).resolve().parent.parent

EMBEDDED_YT_B64 = ""
EMBEDDED_GD_B64 = ""
EMBEDDED_IG_B64 = ""

def ensure_cloud_credentials():
    token_pickle = BASE_DIR / "token.pickle"
    gdrive_token = BASE_DIR / "gdrive_token.pickle"
    ig_session = BASE_DIR / "instagram_session.json"

    # 1. YouTube Token
    if not token_pickle.exists() or token_pickle.stat().st_size == 0:
        b64 = os.getenv("TOKEN_PICKLE_BASE64") or EMBEDDED_YT_B64
        if b64:
            try:
                token_pickle.write_bytes(base64.b64decode(b64))
                print("YouTube token restored from embedded vault.")
            except Exception as e:
                print(f"YouTube restore error: {e}")

    # 2. Google Drive Token
    if not gdrive_token.exists() or gdrive_token.stat().st_size == 0:
        b64 = os.getenv("GDRIVE_TOKEN_BASE64") or EMBEDDED_GD_B64
        if b64:
            try:
                gdrive_token.write_bytes(base64.b64decode(b64))
                print("Google Drive token restored from embedded vault.")
            except Exception as e:
                print(f"GDrive restore error: {e}")

    # 3. Instagram Session
    if not ig_session.exists() or ig_session.stat().st_size == 0:
        raw_ig = os.getenv("INSTAGRAM_SESSION")
        if not raw_ig and EMBEDDED_IG_B64:
            try:
                raw_ig = base64.b64decode(EMBEDDED_IG_B64).decode("utf-8")
            except Exception:
                pass
        if raw_ig:
            try:
                ig_session.write_text(raw_ig, encoding="utf-8")
                print("Instagram session restored from embedded vault.")
            except Exception as e:
                print(f"Instagram restore error: {e}")

if __name__ == "__main__":
    ensure_cloud_credentials()
